!function(Infinity) {};

var undefined = 5;

try {
} catch (eval) {}

import NaN from "foo";

import { undefined } from "bar";

class Infinity {}

var Object;

function f(a, b) {}

// Exception: `undefined` may be shadowed if the variable is never assigned a value.
var undefined;

