namespace foo {}Examples of correct code for this rule when { "allowDeclarations": true }typescriptdeclare module "foo" {}
declare module foo {}
declare namespace foo {}

declare global {
  namespace foo {}
}

declare module foo {
  namespace foo {}
}Examples of incorrect code for this rule when { "allowDeclarations": false }typescriptmodule foo {}
