declare namespace foo {}Examples of correct code for this rule when { "allowDeclarations": false }typescriptdeclare module "foo" {}allowDefinitionFiles ​{ type: boolean, allowDefinitionFiles: true }Examples of incorrect code for this rule when { "allowDefinitionFiles": true }typescript// if outside a d.ts file
