React.createElement("Hello", { style: true });
const styles = true;
React.createElement("div", { style: styles });Examples of correct code for this rule:jsx<div style={{ color: "red" }} />
<Hello style={{ color: "red" }} />
const styles = { color: "red" };
<div style={styles} />

