const QuuxAny = <T extends any>() => {};

function QuuzAny<T extends any>() {}typescriptclass BazAny<T extends any> {
  quxAny<U extends any>() {}
}Examples of correct code for this rule:typescriptinterface Foo<T> {}

type Bar<T> = {};

const Quux = <T>() => {};

function Quuz<T>() {}typescriptclass Baz<T> {
