  } else {
    return z;
  }
}

function foo4() {
  if (error) {
    return "It failed";
  } else if (loading) {
    return "It's still loading";
  }
}allowElseIf: false ​Examples of incorrect code for this rule:javascriptfunction foo() {
  if (error) {
    return "It failed";
  } else if (loading) {
    return "It's still loading";
  }
}Examples of correct code for this rule:javascriptfunction foo() {
