    case Color.Green:
      return "green";
    case Color.Blue:
      return "blue";
    default:
      const _exhaustiveCheck: never = color;
      return _exhaustiveCheck;
  }
}How to use ​To enable this rule in the CLI or using the config file, you can use:CLIConfig (.oxlintrc.json)bashoxlint --deny typescript/switch-exhaustiveness-checkjson{
